//! Database seeder binary for module: survey
//!
//! Generated by metaphor-schema. Do not edit manually.
//!
//! Run with: cargo run --bin survey-seeder
//! Or via CLI: backbone seed run --module survey
//!
//! This binary runs all registered seeders in order.

use anyhow::Result;
use sqlx::postgres::PgPoolOptions;
use std::env;

// Import seeders
use backbone_survey::seeders::SeedQuestionSeeder;
use backbone_survey::seeders::SeedQuestionAnswerSeeder;
use backbone_survey::seeders::SeedSurveyQuestionTriggeringAnswerSeeder;
use backbone_survey::seeders::SeedSurveySeeder;
use backbone_survey::seeders::SeedSurveySurveyRestrictUserSeeder;
use backbone_survey::seeders::SeedSurveySurveyLangSeeder;
use backbone_survey::seeders::SeedUserInputSeeder;
use backbone_survey::seeders::SeedUserInputLineSeeder;
use backbone_survey::seeders::SeedSurveyUserInputPredefinedQuestionSeeder;
use backbone_survey::seeders::Seeder;

#[tokio::main]
async fn main() -> Result<()> {
    let args: Vec<String> = env::args().collect();
    let force = args.iter().any(|a| a == "--force");
    let filter: Option<&str> = args.iter()
        .skip(1)
        .find(|a| !a.starts_with("-"))
        .map(|s| s.as_str());

    let database_url = env::var("DATABASE_URL")
        .map_err(|e| anyhow::anyhow!("DATABASE_URL must be set: {e}"))?;

    println!("Connecting to database...");

    let pool = PgPoolOptions::new()
        .max_connections(5)
        .connect(&database_url)
        .await?;

    println!("Connected to database");
    println!();
    println!("Running seeders for module: survey");
    println!();

    // Register seeders in order
    let mut seeders: Vec<Box<dyn Seeder + Send + Sync>> = Vec::new();
    seeders.push(Box::new(SeedQuestionSeeder::new()));
    seeders.push(Box::new(SeedQuestionAnswerSeeder::new()));
    seeders.push(Box::new(SeedSurveyQuestionTriggeringAnswerSeeder::new()));
    seeders.push(Box::new(SeedSurveySeeder::new()));
    seeders.push(Box::new(SeedSurveySurveyRestrictUserSeeder::new()));
    seeders.push(Box::new(SeedSurveySurveyLangSeeder::new()));
    seeders.push(Box::new(SeedUserInputSeeder::new()));
    seeders.push(Box::new(SeedUserInputLineSeeder::new()));
    seeders.push(Box::new(SeedSurveyUserInputPredefinedQuestionSeeder::new()));

    // Sort by order
    seeders.sort_by_key(|s| s.order());

    // Run seeders
    for seeder in &seeders {
        let name = seeder.name();

        // Apply filter if specified
        if let Some(f) = filter {
            if !name.contains(f) {
                continue;
            }
        }

        if force {
            println!("   Running {}...", name);
            seeder.run(&pool).await?;
            println!("   {} completed", name);
        } else {
            println!("   Checking {}...", name);
            if seeder.should_run(&pool).await? {
                println!("   Running {}...", name);
                seeder.run(&pool).await?;
                println!("   {} completed", name);
            } else {
                println!("   {} already applied, skipping", name);
            }
        }
    }

    println!();
    println!("All seeders completed successfully!");

    Ok(())
}
